<template><div><div class="two-col"><div class="panel"><div style="font-weight:700;margin-bottom:10px">产品分类</div><el-tree class="cat-tree" :data="tree" :props="{label:'name',children:'children'}" node-key="id" :default-expand-all="true" highlight-current @node-click="selectCat"/></div><div><div class="filter-bar"><el-input v-model="keyword" placeholder="搜索产品型号 / 名称" clearable style="width:260px" @keyup.enter="load"/><el-button type="primary" @click="load">搜索</el-button><el-button v-if="auth.isAdmin" type="primary" @click="openAdd">新增产品</el-button></div><div class="table-wrap"><el-table :data="rows" v-loading="loading" style="width:100%"><el-table-column prop="id" label="序号" width="80"/><el-table-column label="产品图片" width="90"><template #default="s"><img v-if="s.row.image" class="thumb" :src="s.row.image"/><span v-else class="muted">暂无</span></template></el-table-column><el-table-column prop="model" label="产品型号" min-width="140"/><el-table-column prop="name" label="产品名称" min-width="180"/><el-table-column label="产品报价" width="120"><template #default="s">¥ {{Number(s.row.price).toFixed(2)}}</template></el-table-column><el-table-column v-if="auth.isAdmin" label="产品成本" width="120"><template #default="s">¥ {{Number(s.row.cost).toFixed(2)}}</template></el-table-column><el-table-column label="录入日期" width="165"><template #default="s">{{fmtDate(s.row.created_at)}}</template></el-table-column><el-table-column label="最近修改日期" width="165"><template #default="s">{{fmtDate(s.row.updated_at)}}</template></el-table-column><el-table-column v-if="auth.isAdmin" label="操作" width="145" fixed="right"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><div style="margin-top:14px;display:flex;justify-content:flex-end"><el-pagination layout="prev,pager,next" :page-size="pageSize" :total="total" v-model:current-page="page" @current-change="load"/></div></div></div></div>
<el-dialog v-model="dialog" :title="form.id?'编辑产品':'新增产品'" width="560px"><el-form label-width="90px"><el-form-item label="三级分类"><el-cascader v-model="form.categoryPath" :options="tree" :props="{value:'id',label:'name',children:'children'}" style="width:100%"/></el-form-item><el-form-item label="产品图片"><el-upload action="/api/upload" :show-file-list="false" :headers="uploadHeaders" :on-success="onUpload"><el-button>上传图片</el-button></el-upload><img v-if="form.image" :src="form.image" class="thumb" style="margin-top:8px"/></el-form-item><el-form-item label="产品型号"><el-input v-model="form.model"/></el-form-item><el-form-item label="产品名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="产品报价"><el-input-number v-model="form.price" :min="0" :precision="2"/></el-form-item><el-form-item v-if="auth.isAdmin" label="产品成本"><el-input-number v-model="form.cost" :min="0" :precision="2"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import {computed,reactive,ref,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api,fmtDate} from '../utils';import {useAuthStore} from '../stores/auth';const auth=useAuthStore(),tree=ref([]),rawCats=ref([]),rows=ref([]),loading=ref(false),keyword=ref(''),categoryId=ref(null),page=ref(1),pageSize=ref(20),total=ref(0),dialog=ref(false);const blank=()=>({id:null,categoryPath:[],model:'',name:'',image:'',price:0,cost:0});const form=reactive(blank());const uploadHeaders=computed(()=>({Authorization:`Bearer ${auth.token}`}));function buildTree(items){const m=new Map(items.map(x=>[x.id,{...x,children:[]} ]));const root=[];for(const x of m.values()){if(x.parent_id)m.get(x.parent_id)?.children.push(x);else root.push(x)}return root}async function loadCats(){const {data}=await api.get('/categories');rawCats.value=data.items;tree.value=buildTree(data.items)}async function load(){loading.value=true;try{const {data}=await api.get('/products',{params:{categoryId:categoryId.value||undefined,keyword:keyword.value||undefined,page:page.value,pageSize:pageSize.value}});rows.value=data.items;total.value=data.total}catch(e){ElMessage.error(e.response?.data?.message||'加载失败')}finally{loading.value=false}}function selectCat(node){categoryId.value=node.id;page.value=1;load()}function openAdd(){Object.assign(form,blank());dialog.value=true}function edit(r){Object.assign(form,{...blank(),...r,categoryPath:getPath(r.category_id)});dialog.value=true}function getPath(id){const out=[];let cur=rawCats.value.find(x=>x.id===id);while(cur){out.unshift(cur.id);cur=rawCats.value.find(x=>x.id===cur.parent_id)}return out}function onUpload(res){form.image=res.url}async function save(){const category=form.categoryPath.at(-1);if(!category||!form.model||!form.name)return ElMessage.warning('请填写分类、型号、名称');try{const payload={categoryId:category,model:form.model,name:form.name,image:form.image,price:form.price,cost:form.cost};if(form.id)await api.put(`/products/${form.id}`,payload);else await api.post('/products',payload);ElMessage.success('保存成功');dialog.value=false;load()}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}}async function remove(id){await ElMessageBox.confirm('确定删除这个产品吗？','提示');try{await api.delete(`/products/${id}`);ElMessage.success('删除成功');load()}catch(e){ElMessage.error(e.response?.data?.message||'删除失败')}}onMounted(async()=>{await loadCats();await load()})</script>
